<script setup lang="ts">
import { ref } from "vue";import { useRouter } from "vue-router";import { useLicenseStore } from "../license/store";
const license=useLicenseStore(),router=useRouter(),code=ref("");async function activate(){if(await license.activate(code.value))await router.replace("/")}async function copyDevice(){await navigator.clipboard.writeText(license.status?.deviceShortCode??"")}
</script>
<template><div class="activation"><section><div class="brand">BAG LAB</div><h1>激活袋研官矩阵混剪工作台</h1><p>首次激活需联网，激活码将绑定当前设备。</p><label>设备短码</label><div class="device"><code>{{license.status?.deviceShortCode??'------------'}}</code><button @click="copyDevice">复制</button></div><label>激活码</label><input v-model="code" autocomplete="off" placeholder="BAGL-XXXXX-XXXXX-XXXXX" @keyup.enter="activate"/><button class="activate" :disabled="license.loading||code.length<12" @click="activate">{{license.loading?'正在验证…':'立即激活'}}</button><p v-if="license.error" class="error">{{license.error}}</p><small>仅上传经 SHA-256 处理的设备指纹，不上传完整硬件信息。</small></section></div></template>
<style scoped>.activation{min-height:100vh;display:grid;place-items:center;background:radial-gradient(circle at 20% 20%,#dfeaff,#f6f8fc 55%)}section{width:min(480px,calc(100vw - 48px));background:white;padding:40px;border-radius:24px;box-shadow:0 24px 80px #23457b22}.brand{letter-spacing:.28em;color:#4169aa;font-weight:700}h1{font-size:26px;margin:12px 0}p{color:#647089}label{display:block;margin:20px 0 8px;font-weight:600}.device{display:flex;gap:10px}.device code,input{flex:1;border:1px solid #d7dfec;border-radius:10px;padding:12px}input{width:calc(100% - 26px);font:inherit}.device button,.activate{border:0;border-radius:10px;background:#2855a1;color:white;padding:0 18px}.activate{width:100%;padding:13px;margin-top:16px;font:inherit}.error{color:#c0392b;background:#fff1ef;padding:10px;border-radius:8px}small{display:block;margin-top:20px;color:#8a94a7}</style>
